// Helper function to count the number of opening brackets
function CountOpenBrackets(brackets: string): int
    requires brackets != null
    ensures Result >= 0
{
    var count := 0;
    var i := 0;
    while i < brackets.Length
        invariant 0 <= i <= brackets.Length
        invariant count == CountOpenBrackets(brackets[0..i])
    {
        if brackets[i] == '<' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to count the number of closing brackets
function CountCloseBrackets(brackets: string): int
    requires brackets != null
    ensures Result >= 0
{
    var count := 0;
    var i := 0;
    while i < brackets.Length
        invariant 0 <= i <= brackets.Length
        invariant count == CountCloseBrackets(brackets[0..i])
    {
        if brackets[i] == '>' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

// Helper function to check that every opening bracket has a corresponding closing bracket
function EveryOpenHasClose(brackets: string): bool
    requires brackets != null
    ensures Result == true || Result == false
{
    var openCount := 0;
    var i := 0;
    while i < brackets.Length
        invariant 0 <= i <= brackets.Length
        invariant openCount >= 0
        invariant openCount == CountOpenBrackets(brackets[0..i]) - CountCloseBrackets(brackets[0..i])
    {
        if brackets[i] == '<' {
            openCount := openCount + 1;
        } else if brackets[i] == '>' {
            openCount := openCount - 1;
        }
        i := i + 1;
    }
    return openCount == 0;
}
